const q=$('Prepare Question').first().json.question;
const tokenize=s=>String(s||'').toLowerCase().match(/[a-z0-9]+/g)||[];
const corpus=$input.all().flatMap(x=>Array.isArray(x.json)?x.json:Array.isArray(x.json.documents)?x.json.documents:[x.json]);
if(corpus.length<1)throw new Error('No keyword documents loaded');
const docs=corpus.filter(d=>d.document_id&&Array.isArray(d.sections)).map(d=>{
 const content=['# '+d.title,...d.sections.map(s=>'## '+s.heading+'\n'+s.text)].join('\n\n');
 return {id:d.document_id,title:d.title,content,metadata:{document_id:d.document_id,title:d.title,department:d.department,region:d.region,version:d.version,status:d.status,access_level:d.access_level,source_path:d.file_path}};
});
const query=tokenize(q);const D=docs.length;
const tfs=docs.map(d=>{const a=tokenize(d.title+' '+d.title+' '+d.content);const freq={};for(const t of a)freq[t]=(freq[t]||0)+1;return {len:a.length,freq}});
const avg=tfs.reduce((a,b)=>a+b.len,0)/Math.max(1,D);
const df={};for(const t of [...new Set(query)])df[t]=tfs.filter(x=>x.freq[t]>0).length;
const scored=docs.map((d,i)=>{let score=0;for(const t of query){const f=tfs[i].freq[t]||0;if(!f)continue;const idf=Math.log(1+(D-(df[t]||0)+0.5)/((df[t]||0)+0.5));score+=idf*f*2.2/(f+1.2*(0.25+0.75*tfs[i].len/avg));}return {doc:d,score};}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,12);
const dense=$items('Pinecone Dense Search').map(x=>x.json).flatMap(x=>Array.isArray(x)?x:x.documents&&Array.isArray(x.documents)?x.documents:[x]);
const denseDocs=dense.map((x,i)=>{const d=x.document||x;const metadata=d.metadata||x.metadata||{};return {id:metadata.document_id||d.document_id||x.document_id,title:metadata.title||x.title||'',content:d.pageContent||d.page_content||d.text||x.pageContent||x.text||'',metadata,rank:i+1};}).filter(x=>x.id);
const candidates=new Map();
for(const [i,x] of scored.entries()){const id=x.doc.id;const old=candidates.get(id)||{...x.doc,score:0,via:[]};old.score+=1/(60+i+1);old.via.push('keyword');candidates.set(id,old);}
for(const x of denseDocs){const old=candidates.get(x.id)||{id:x.id,title:x.title,content:x.content,metadata:x.metadata,score:0,via:[]};old.score+=1/(60+x.rank);old.via.push('dense');candidates.set(x.id,old);}
const ranked=[...candidates.values()].sort((a,b)=>b.score-a.score).slice(0,10);
const prompt=ranked.map((x,i)=>({id:x.id,title:x.title,text:x.content.slice(0,1500),fusedRank:i+1,via:x.via})); 
return [{json:{question:q,sessionId:$('Prepare Question').first().json.sessionId,candidates:ranked,rerankInput:JSON.stringify(prompt)}}];

const prev=$('Hybrid BM25 + RRF').first().json;const raw=$input.first().json.text||$input.first().json.output||'';let ids=[];try{const cleaned=String(raw).replace(/^```(?:json)?/,'').replace(/```$/,'').trim();const obj=JSON.parse(cleaned);ids=Array.isArray(obj)?obj:(obj.ranked_ids||obj.ids||[]);}catch{}const lookup=new Map(prev.candidates.map(x=>[x.id,x]));const selected=[...new Set(ids)].filter(id=>lookup.has(id)).slice(0,5).map(id=>lookup.get(id));for(const d of prev.candidates){if(selected.length>=5)break;if(!selected.some(x=>x.id===d.id))selected.push(d);}const contexts=selected.map((d,i)=>'[SOURCE '+(i+1)+'] ID: '+d.id+' | '+d.title+' | status: '+(d.metadata.status||'')+' | region: '+(d.metadata.region||'')+'
'+d.content.slice(0,2400)).join('

');return [{json:{question:prev.question,sessionId:prev.sessionId,sources:selected.map(d=>({document_id:d.id,title:d.title,department:d.metadata.department||'',region:d.metadata.region||'',status:d.metadata.status||''})),context:contexts,retrieval:{dense_count:prev.candidates.filter(x=>x.via.includes('dense')).length,keyword_count:prev.candidates.filter(x=>x.via.includes('keyword')).length,reranked_count:selected.length,method:'BM25 + Pinecone dense + RRF + LLM rerank'}}}];
